use licentivo_launch::{Application,Config,Failure};use serde_json::{json,Value};use std::{fs,path::PathBuf,process::Command};
fn run()->Result<(),Failure>{let root=PathBuf::from("/home/spf86/launch-sdk-renewal-20261101");let report:Value=serde_json::from_slice(&fs::read(root.join("meter-public.json"))?).map_err(|_|Failure::new("FIXTURE_JSON"))?;let secret:Value=serde_json::from_slice(&fs::read(root.join("deployment-private.json"))?).map_err(|_|Failure::new("FIXTURE_JSON"))?;let c=&report["config"];let mut product=report["product_config"].clone();product["allow_http"]=json!(true);let cfg=Config::new_with_http(c["merchant_origin"].as_str().unwrap(),c["launch_product_id"].as_str().unwrap(),c["licentivo_product_id"].as_str().unwrap(),"sandbox",true)?;let mut app=Application::new(cfg,product,root.join("runtime/rust"))?;app.login(&std::env::var("LAUNCH_EMAIL").unwrap(),secret["customer_password"].as_str().unwrap())?;let operation=std::env::var("LAUNCH_OPERATION").unwrap();let phase=std::env::var("LAUNCH_PHASE").unwrap();let mut calls=0;let _=app.run_metered_feature("export",3,&operation,||{calls+=1;let status=Command::new("python3").arg(root.join("long_business.py")).status()?;if !status.success(){return Err(Failure::new("BUSINESS_HELPER_FAILED"))}Ok(())})?;if phase=="replay"{app.resolve_metered_feature(&operation,true)?;}if calls!=if phase=="run"{1}else{0}{return Err(Failure::new("CALLBACK_COUNT"))}println!("{}",json!({"ok":true,"language":"rust","phase":phase,"callbacks":calls}));app.close();Ok(())}
fn main(){if let Err(error)=run(){eprintln!("{}",error.code);std::process::exit(1)}}
